select t.rule_name,t.rule_name ruleName,t.remark,t.status_cd,t.status_cd statusCd,t.rule_id,t.rule_id
ruleId,t.template_id,t.template_id templateId,t.community_id,t.community_id communityId,t.limit_time limitTime
from event_rule t
left join event_template et on t.template_id = et.template_id
where 1 =1 and et.status_cd = '0'

    and t.rule_name= #{ruleName}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.rule_id= #{ruleId}


    and t.template_id= #{templateId}


    and t.community_id= #{communityId}

order by t.create_time desc

    limit #{page}, #{row}

